import React, { useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import "../styles/UserPages.css";
import { useNavigate } from "react-router-dom";
import API_BASE_URL from "../config";

const CreateRentalListing = () => {
  const navigate = useNavigate();

  const [form, setForm] = useState({
    title: "",
    description: "",
    price: "",
    duration: "",
    condition: "",
    image: null,
  });

  const [preview, setPreview] = useState(null);

  const handleChange = (e) => {
    const { name, value } = e.target;

    if (name === "price") {
      const priceVal = parseFloat(value);
      if (priceVal > 10000 || (priceVal < 1 && value !== "")) return;
    }

    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleImageUpload = (e) => {
    const file = e.target.files[0];
    setForm((prev) => ({ ...prev, image: file }));
    setPreview(URL.createObjectURL(file));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const { title, description, price, duration, condition, image } = form;

    if (!title || !description || !price || !duration || !condition) {
      alert("Please fill out all fields.");
      return;
    }

    if (title.length > 50) {
      alert("Title too long. Max 50 characters.");
      return;
    }

    if (description.length > 200) {
      alert("Description too long. Max 200 characters.");
      return;
    }

    const priceVal = parseFloat(price);
    if (isNaN(priceVal) || priceVal < 1 || priceVal > 10000) {
      alert("Price must be between $1 and $10,000.");
      return;
    }

    const sellerId = sessionStorage.getItem("userId");
    if (!sellerId) {
      alert("You must be logged in to post a rental.");
      return;
    }

    try {
      let imageBase64 = null;

      if (image) {
        const reader = new FileReader();
        reader.onloadend = async () => {
          imageBase64 = reader.result;

          const response = await fetch(`${API_BASE_URL}/api/rentals`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              seller_id: sellerId,
              title,
              description,
              price,
              duration,
              condition,
              image: imageBase64,
            }),
          });

          if (response.ok) {
            alert("Rental listing posted!");
            setForm({
              title: "",
              description: "",
              price: "",
              duration: "",
              condition: "",
              image: null,
            });
            setPreview(null);
            navigate("/browse-rentals");
          } else {
            alert("Failed to submit rental.");
          }
        };
        reader.readAsDataURL(image);
      } else {
        const response = await fetch(`${API_BASE_URL}/api/rentals`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            seller_id: sellerId,
            title,
            description,
            price,
            duration,
            condition,
            image: null,
          }),
        });

        if (response.ok) {
          alert("Rental listing posted!");
          setForm({
            title: "",
            description: "",
            price: "",
            duration: "",
            condition: "",
            image: null,
          });
          setPreview(null);
          navigate("/browse-rentals");
        } else {
          alert("Failed to submit rental.");
        }
      }
    } catch (err) {
      console.error("Submit error:", err);
      alert("An error occurred while posting the rental.");
    }
  };

  return (
    <div>
      <Navbar />
      <main className="create-listing-wrapper">
        <h2>Create Rental Listing</h2>
        <form className="create-listing-form" onSubmit={handleSubmit}>
          <input
            type="text"
            name="title"
            placeholder="Item Title (max 50 characters)"
            value={form.title}
            onChange={handleChange}
            maxLength={50}
            required
          />
          <small>{form.title.length}/50 characters</small>

          <textarea
            name="description"
            placeholder="Item Description (max 200 characters)"
            value={form.description}
            onChange={handleChange}
            rows={5}
            maxLength={200}
            required
          />
          <small>{form.description.length}/200 characters</small>

          <input
            type="number"
            name="price"
            placeholder="Rental Price (USD)"
            value={form.price}
            onChange={handleChange}
            min={1}
            max={10000}
            required
          />
          <small>Price must be between $1 and $10,000</small>

          <select name="duration" value={form.duration} onChange={handleChange} required>
            <option value="">Select Rental Duration</option>
            <option value="1 day">1 Day</option>
            <option value="3 days">3 Days</option>
            <option value="1 week">1 Week</option>
            <option value="1 month">1 Month</option>
          </select>

          <select name="condition" value={form.condition} onChange={handleChange} required>
            <option value="">Select Condition</option>
            <option value="new">New</option>
            <option value="like-new">Like New</option>
            <option value="good">Good</option>
            <option value="fair">Fair</option>
            <option value="used">Used</option>
          </select>

          <input type="file" accept="image/*" onChange={handleImageUpload} />

          {preview && <img src={preview} alt="Preview" className="image-preview" />}

          <button type="submit">Submit Rental</button>
        </form>
      </main>
      <Footer />
    </div>
  );
};

export default CreateRentalListing;
